"use client";

import React, { useMemo, useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import {
  ArrowRight,
  Copy,
  FileText,
  Palette,
  Search,
  SlidersHorizontal,
  Terminal,
} from "lucide-react";
import { usePortfolio } from "@/context/PortfolioContext";
import { ThemePresetId } from "@/types/portfolio";

export default function CommandPalette({
  onOpenResume,
}: {
  onOpenResume: () => void;
}) {
  const {
    config,
    commandOpen,
    setCommandOpen,
    setStudioOpen,
    setStudioTab,
    updateSettings,
  } = usePortfolio();
  const [query, setQuery] = useState("");
  const [copiedEmail, setCopiedEmail] = useState(false);

  const actions = useMemo(
    () => [
      {
        id: "nav-skills",
        label: "Jump to 3D Skill Constellation",
        group: "Navigation",
        icon: Terminal,
        run: () => document.getElementById("skills")?.scrollIntoView({ behavior: "smooth" }),
      },
      {
        id: "nav-dsa",
        label: "Open DSA & Code Lab (Java / C++ / Python)",
        group: "Navigation",
        icon: Terminal,
        run: () => document.getElementById("dsa-lab")?.scrollIntoView({ behavior: "smooth" }),
      },
      {
        id: "nav-projects",
        label: "Jump to Projects Showcase",
        group: "Navigation",
        icon: ArrowRight,
        run: () => document.getElementById("projects")?.scrollIntoView({ behavior: "smooth" }),
      },
      {
        id: "studio-profile",
        label: "Portfolio Studio: Edit Profile & Bio",
        group: "Studio",
        icon: SlidersHorizontal,
        run: () => {
          setStudioTab("profile");
          setStudioOpen(true);
        },
      },
      {
        id: "studio-projects",
        label: "Portfolio Studio: Manage Projects",
        group: "Studio",
        icon: SlidersHorizontal,
        run: () => {
          setStudioTab("projects");
          setStudioOpen(true);
        },
      },
      {
        id: "resume",
        label: "Generate Printable Resume / PDF",
        group: "Export",
        icon: FileText,
        run: () => onOpenResume(),
      },
      {
        id: "copy-email",
        label: `Copy Email (${config.profile.email})`,
        group: "Contact",
        icon: Copy,
        run: async () => {
          await navigator.clipboard?.writeText(config.profile.email);
          setCopiedEmail(true);
          window.setTimeout(() => setCopiedEmail(false), 1200);
        },
      },
      ...(
        [
          ["cryo", "Theme: Cryo Cyan"],
          ["indigo", "Theme: Electric Indigo"],
          ["emerald", "Theme: Emerald Matrix"],
          ["amber", "Theme: Solar Amber"],
        ] as [ThemePresetId, string][]
      ).map(([id, label]) => ({
        id: `theme-${id}`,
        label,
        group: "Themes",
        icon: Palette,
        run: () => updateSettings({ theme: id }),
      })),
    ],
    [config.profile.email, onOpenResume, setStudioOpen, setStudioTab, updateSettings]
  );

  const filtered = actions.filter((a) =>
    a.label.toLowerCase().includes(query.trim().toLowerCase())
  );

  return (
    <AnimatePresence>
      {commandOpen && (
        <>
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => setCommandOpen(false)}
            className="fixed inset-0 z-50 bg-slate-950/75 backdrop-blur-sm"
          />
          <motion.div
            initial={{ opacity: 0, y: -16, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -10, scale: 0.98 }}
            className="fixed left-1/2 top-24 z-50 w-[92vw] max-w-xl -translate-x-1/2 overflow-hidden rounded-2xl border border-slate-700/80 bg-slate-950/95 shadow-2xl backdrop-blur-2xl"
          >
            <div className="flex items-center gap-3 border-b border-slate-800 px-4 py-3">
              <Search className="h-4 w-4 text-slate-400" />
              <input
                autoFocus
                placeholder="Type a command, section, or theme..."
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Escape") setCommandOpen(false);
                }}
                className="flex-1 bg-transparent text-sm text-white placeholder:text-slate-500 focus:outline-none"
              />
              <kbd className="rounded border border-slate-700 bg-slate-900 px-1.5 py-0.5 text-[10px] font-mono text-slate-400">
                ESC
              </kbd>
            </div>

            <div className="max-h-80 overflow-y-auto p-2 space-y-1">
              {filtered.length === 0 ? (
                <div className="py-8 text-center text-xs text-slate-500">
                  No matching commands.
                </div>
              ) : (
                filtered.map((item) => {
                  const Icon = item.icon;
                  return (
                    <button
                      key={item.id}
                      onClick={() => {
                        item.run();
                        setCommandOpen(false);
                        setQuery("");
                      }}
                      className="flex w-full items-center justify-between rounded-xl px-3 py-2.5 text-left text-sm text-slate-200 hover:bg-slate-800/80 cursor-pointer"
                    >
                      <span className="flex items-center gap-2.5">
                        <Icon className="h-4 w-4 text-sky-400" />
                        {item.label}
                      </span>
                      <span className="text-[10px] font-mono text-slate-500">{item.group}</span>
                    </button>
                  );
                })
              )}
            </div>

            {copiedEmail && (
              <div className="border-t border-slate-800 bg-emerald-500/10 px-4 py-2 text-xs text-emerald-300">
                Copied {config.profile.email} to clipboard
              </div>
            )}
          </motion.div>
        </>
      )}
    </AnimatePresence>
  );
}
