export type AlgorithmId = "quicksort" | "mergesort" | "binarysearch" | "dijkstra";
export type CodeLanguage = "java" | "cpp" | "python";

export interface ArrayStep {
  kind: "array";
  values: number[];
  active: number[];
  sorted: number[];
  pivot?: number;
  message: string;
  comparisons: number;
  swaps: number;
}

export interface GridStep {
  kind: "grid";
  rows: number;
  cols: number;
  start: [number, number];
  end: [number, number];
  walls: string[];
  visited: string[];
  frontier: string[];
  path: string[];
  message: string;
  comparisons: number;
  swaps: number;
}

export type DsaStep = ArrayStep | GridStep;

export interface AlgorithmDefinition {
  id: AlgorithmId;
  name: string;
  category: string;
  complexity: {
    time: string;
    space: string;
  };
  summary: string;
  code: Record<CodeLanguage, string>;
}

