export function generateQuickSortSteps(input: number[]): ArrayStep[] {
  const arr = [...input];
  const steps: ArrayStep[] = [];
  const sorted = new Set<number>();
  let comparisons = 0;
  let swaps = 0;

  steps.push({
    kind: "array",
    values: [...arr],
    active: [],
    sorted: [],
    message: "Initialized array for Quick Sort",
    comparisons,
    swaps,
  });

  function partition(low: number, high: number): number {
    const pivot = arr[high];
    let i = low - 1;
    for (let j = low; j < high; j++) {
      comparisons++;
      steps.push({
        kind: "array",
        values: [...arr],
        active: [j, high],
        sorted: [...sorted],
        pivot: high,
        message: `Comparing arr[${j}]=${arr[j]} against pivot=${pivot}`,
        comparisons,
        swaps,
      });
      if (arr[j] <= pivot) {
        i++;
        if (i !== j) {
          [arr[i], arr[j]] = [arr[j], arr[i]];
          swaps++;
          steps.push({
            kind: "array",
            values: [...arr],
            active: [i, j],
            sorted: [...sorted],
            pivot: high,
            message: `Swapped index ${i} and ${j}`,
            comparisons,
            swaps,
          });
        }
      }
    }
    if (i + 1 !== high) {
      [arr[i + 1], arr[high]] = [arr[high], arr[i + 1]];
      swaps++;
    }
    sorted.add(i + 1);
    steps.push({
      kind: "array",
      values: [...arr],
      active: [i + 1],
      sorted: [...sorted],
      message: `Pivot ${pivot} locked at sorted index ${i + 1}`,
      comparisons,
      swaps,
    });
    return i + 1;
  }

  function sort(low: number, high: number) {
    if (low < high) {
      const pi = partition(low, high);
      sort(low, pi - 1);
      sort(pi + 1, high);
    } else if (low === high && low >= 0 && low < arr.length) {
      sorted.add(low);
    }
  }

  sort(0, arr.length - 1);
  steps.push({
    kind: "array",
    values: [...arr],
    active: [],
    sorted: arr.map((_, idx) => idx),
    message: "Quick Sort complete — array fully sorted",
    comparisons,
    swaps,
  });
  return steps;
}

export function generateMergeSortSteps(input: number[]): ArrayStep[] {
  const arr = [...input];
  const steps: ArrayStep[] = [];
  let comparisons = 0;
  let swaps = 0;

  steps.push({
    kind: "array",
    values: [...arr],
    active: [],
    sorted: [],
    message: "Initialized array for Merge Sort",
    comparisons,
    swaps,
  });

  function merge(l: number, m: number, r: number) {
    const left = arr.slice(l, m + 1);
    const right = arr.slice(m + 1, r + 1);
    let i = 0;
    let j = 0;
    let k = l;

    while (i < left.length && j < right.length) {
      comparisons++;
      if (left[i] <= right[j]) {
        arr[k] = left[i++];
      } else {
        arr[k] = right[j++];
        swaps++;
      }
      steps.push({
        kind: "array",
        values: [...arr],
        active: [k],
        sorted: l === 0 && r === arr.length - 1 ? Array.from({ length: k + 1 }, (_, idx) => idx) : [],
        message: `Merged value ${arr[k]} into position ${k}`,
        comparisons,
        swaps,
      });
      k++;
    }
    while (i < left.length) {
      arr[k] = left[i++];
      steps.push({
        kind: "array",
        values: [...arr],
        active: [k],
        sorted: l === 0 && r === arr.length - 1 ? Array.from({ length: k + 1 }, (_, idx) => idx) : [],
        message: `Flushed remaining left value ${arr[k]} to ${k}`,
        comparisons,
        swaps,
      });
      k++;
    }
    while (j < right.length) {
      arr[k] = right[j++];
      steps.push({
        kind: "array",
        values: [...arr],
        active: [k],
        sorted: l === 0 && r === arr.length - 1 ? Array.from({ length: k + 1 }, (_, idx) => idx) : [],
        message: `Flushed remaining right value ${arr[k]} to ${k}`,
        comparisons,
        swaps,
      });
      k++;
    }
  }

  function sort(l: number, r: number) {
    if (l >= r) return;
    const m = Math.floor((l + r) / 2);
    sort(l, m);
    sort(m + 1, r);
    merge(l, m, r);
  }

  sort(0, arr.length - 1);
  steps.push({
    kind: "array",
    values: [...arr],
    active: [],
    sorted: arr.map((_, idx) => idx),
    message: "Merge Sort complete — array fully sorted",
    comparisons,
    swaps,
  });
  return steps;
}

export function generateBinarySearchSteps(input: number[]): ArrayStep[] {
  const sortedArr = [...input].sort((a, b) => a - b);
  const targetIdx = Math.floor(sortedArr.length * 0.65);
  const target = sortedArr[targetIdx];
  const steps: ArrayStep[] = [];
  let low = 0;
  let high = sortedArr.length - 1;
  let comparisons = 0;

  steps.push({
    kind: "array",
    values: sortedArr,
    active: [low, high],
    sorted: [],
    message: `Searching sorted array for target = ${target}`,
    comparisons,
    swaps: 0,
  });

  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    comparisons++;
    steps.push({
      kind: "array",
      values: sortedArr,
      active: [low, mid, high],
      sorted: [],
      pivot: mid,
      message: `Checking mid=${mid} (val=${sortedArr[mid]}) against target=${target}`,
      comparisons,
      swaps: 0,
    });
    if (sortedArr[mid] === target) {
      steps.push({
        kind: "array",
        values: sortedArr,
        active: [mid],
        sorted: [mid],
        pivot: mid,
        message: `Found target ${target} at index ${mid} in ${comparisons} comparisons!`,
        comparisons,
        swaps: 0,
      });
      break;
    }
    if (sortedArr[mid] < target) {
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }

  return steps;
}

export function generateGridPathSteps(): GridStep[] {
  const rows = 7;
  const cols = 11;
  const start: [number, number] = [3, 1];
  const end: [number, number] = [3, 9];
  const wallList: [number, number][] = [
    [1, 4],
    [2, 4],
    [3, 4],
    [4, 4],
    [5, 4],
    [1, 7],
    [2, 7],
    [4, 7],
    [5, 7],
    [6, 7],
  ];
  const key = (r: number, c: number) => `${r},${c}`;
  const walls = new Set(wallList.map(([r, c]) => key(r, c)));
  const visited = new Set<string>([key(start[0], start[1])]);
  const parent = new Map<string, string>();
  const queue: [number, number][] = [start];
  const steps: GridStep[] = [];
  let comparisons = 0;

  steps.push({
    kind: "grid",
    rows,
    cols,
    start,
    end,
    walls: [...walls],
    visited: [...visited],
    frontier: [key(start[0], start[1])],
    path: [],
    message: "Initialized wavefront from start node",
    comparisons,
    swaps: 0,
  });

  const dirs = [
    [0, 1],
    [1, 0],
    [-1, 0],
    [0, -1],
  ];

  let found = false;
  while (queue.length > 0 && !found) {
    const levelSize = queue.length;
    const frontierKeys: string[] = [];
    for (let i = 0; i < levelSize; i++) {
      const [r, c] = queue.shift()!;
      if (r === end[0] && c === end[1]) {
        found = true;
        break;
      }
      for (const [dr, dc] of dirs) {
        const nr = r + dr;
        const nc = c + dc;
        const nk = key(nr, nc);
        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !walls.has(nk) && !visited.has(nk)) {
          comparisons++;
          visited.add(nk);
          parent.set(nk, key(r, c));
          queue.push([nr, nc]);
          frontierKeys.push(nk);
          if (nr === end[0] && nc === end[1]) {
            found = true;
          }
        }
      }
    }
    if (frontierKeys.length > 0) {
      steps.push({
        kind: "grid",
        rows,
        cols,
        start,
        end,
        walls: [...walls],
        visited: [...visited],
        frontier: frontierKeys,
        path: [],
        message: `Expanded wavefront (${visited.size} cells explored)`,
        comparisons,
        swaps: 0,
      });
    }
  }

  const path: string[] = [];
  let cur: string | undefined = key(end[0], end[1]);
  while (cur) {
    path.unshift(cur);
    cur = parent.get(cur);
  }

  steps.push({
    kind: "grid",
    rows,
    cols,
    start,
    end,
    walls: [...walls],
    visited: [...visited],
    frontier: [],
    path,
    message: `Shortest path reconstructed (${path.length - 1} steps)`,
    comparisons,
    swaps: path.length - 1,
  });

  return steps;
}
